<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ArrowLeft, Maximize2, Minimize2, RotateCcw, Send, X } from "lucide-vue-next";
import { ContentService } from "@/api/contentService";
import type { CommentDocumentV1, CommentItem, CommentSort, PostAsset } from "@/api/types";
import CommentDocumentEditor from "@/features/comments/CommentDocumentEditor.vue";
import ThreadComment from "@/features/comments/ThreadComment.vue";
import { commentDocumentText, emptyCommentDocument, plainCommentDocument } from "@/features/comments/commentDocument";
import { deleteCommentDraft, loadCommentDraft, saveCommentDraft } from "@/features/comments/commentDrafts";
import { commentMediaAssets, fileToPostAsset, isAssetReady } from "@/features/mediaProject/mediaAssets";

const route=useRoute();const router=useRouter();const postId=computed(()=>String(route.params.postId||""));
const roots=ref<CommentItem[]>([]);const threads=ref<Record<string,CommentItem[]>>({});const replyCursors=ref<Record<string,string|null>>({});const loadedIds=ref<Record<string,boolean>>({});const loadingIds=ref<Record<string,boolean>>({});
const rootCursor=ref<string|null>(null);const sort=ref<CommentSort>("TOP");const loading=ref(true);const sending=ref(false);const allowComments=ref(true);const isPostOwner=ref(false);const activeOwnerId=ref("anonymous");
const replyingTo=ref<CommentItem|null>(null);const editingComment=ref<CommentItem|null>(null);const document=ref<CommentDocumentV1>(emptyCommentDocument());const attachments=ref<PostAsset[]>([]);const fullscreen=ref(false);const restored=ref(false);const errorMessage=ref("");
const attachmentFiles=new Map<string,File>();const attachmentControllers=new Map<string,AbortController>();let draftTimer=0;
const attachmentsReady=computed(()=>attachments.value.every(isAssetReady));const visibleLength=computed(()=>commentDocumentText(document.value).length);
const rootTarget=computed(()=>replyingTo.value?(replyingTo.value.parentId||replyingTo.value.id):null);
const draftKey=computed(()=>`${activeOwnerId.value}:${postId.value}:${rootTarget.value||"root"}:${replyingTo.value?.id||"none"}:${editingComment.value?.id||"create"}`);

onMounted(async()=>{window.addEventListener("popstate",onPopState);window.addEventListener("keydown",onKeydown);await Promise.all([loadRoot(),loadPermissions()]);await restoreDraft();const target=typeof route.params.commentId==="string"?route.params.commentId:"";if(target){await loadDirectThread(target);await nextTick();window.setTimeout(()=>documentGlobal().getElementById(`comment-${target}`)?.scrollIntoView({block:"center"}),100);}});
onBeforeUnmount(()=>{window.removeEventListener("popstate",onPopState);window.removeEventListener("keydown",onKeydown);window.clearTimeout(draftTimer);attachmentControllers.forEach((controller)=>controller.abort());attachments.value.forEach(revokePreview);});
watch([document,attachments],()=>{if(!restored.value)return;window.clearTimeout(draftTimer);draftTimer=window.setTimeout(()=>void saveCommentDraft(draftKey.value,{document:document.value,attachments:attachments.value.map(({previewUrl:_preview,...asset})=>asset),savedAt:Date.now()}),350);},{deep:true});

function documentGlobal(){return window.document;}
async function restoreDraft(){const saved=await loadCommentDraft(draftKey.value);if(saved){document.value=saved.document;attachments.value=saved.attachments;}restored.value=true;}
async function loadPermissions(){try{const[post,actor]=await Promise.all([ContentService.post(postId.value),ContentService.currentActor()]);allowComments.value=post?.allowComments!==false;isPostOwner.value=Boolean(post&&actor.activeOwner.id===(post.ownerId||post.authorId));activeOwnerId.value=`USER:${actor.activeOwner.id}`;}catch{/* Public reading remains available. */}}
async function loadRoot(append=false){loading.value=!append;try{const page=await ContentService.commentThread({postId:postId.value,parentId:null,cursor:append?rootCursor.value:null,sort:sort.value,limit:30});roots.value=append?mergeComments(roots.value,page.comments):page.comments;rootCursor.value=page.nextCursor||null;}catch(error){showError(error,"Не удалось загрузить комментарии");}finally{loading.value=false;}}
async function changeSort(next:CommentSort){if(sort.value===next)return;sort.value=next;threads.value={};replyCursors.value={};loadedIds.value={};rootCursor.value=null;await loadRoot();}
async function loadReplies(root:CommentItem,append=false){if(root.parentId)return;if((!append&&loadedIds.value[root.id])||loadingIds.value[root.id])return;const cursor=append?replyCursors.value[root.id]:null;if(append&&!cursor)return;loadingIds.value={...loadingIds.value,[root.id]:true};try{const page=await ContentService.commentThread({postId:postId.value,parentId:root.id,cursor,sort:"OLDEST",limit:30});threads.value={...threads.value,[root.id]:append?mergeComments(threads.value[root.id]||[],page.comments):page.comments};replyCursors.value={...replyCursors.value,[root.id]:page.nextCursor||null};loadedIds.value={...loadedIds.value,[root.id]:true};}catch(error){showError(error,"Не удалось загрузить ответы");}finally{loadingIds.value={...loadingIds.value,[root.id]:false};}}
async function loadDirectThread(targetId:string){try{const target=await ContentService.comment(targetId);if(!target)return;const root=target.parentId?await ContentService.comment(target.parentId):target;if(!root)return;roots.value=mergeComments(roots.value,[root]);if(target.parentId){threads.value={...threads.value,[root.id]:mergeComments(threads.value[root.id]||[],[target])};loadedIds.value={...loadedIds.value,[root.id]:true};}}catch{/* Private/deleted permalink remains absent. */}}

async function switchTarget(target:CommentItem|null){await persistCurrentDraft();replyingTo.value=target;editingComment.value=null;attachments.value.forEach(revokePreview);attachments.value=[];document.value=target?mentionDocument(target):emptyCommentDocument();restored.value=false;await restoreDraft();}
function reply(comment:CommentItem){void switchTarget(comment);}
async function edit(comment:CommentItem){await persistCurrentDraft();replyingTo.value=null;editingComment.value=comment;document.value=comment.document||plainCommentDocument(comment.text);attachments.value=[...(comment.attachments||comment.assets||[])];restored.value=true;openFullscreen();}
function mentionDocument(comment:CommentItem):CommentDocumentV1{const label=`@${comment.author?.username||comment.authorName||"user"} `;return{version:1,blocks:[{id:crypto.randomUUID(),type:"PARAGRAPH",content:[{text:label,marks:[{type:"MENTION",ownerType:comment.ownerType||"USER",ownerId:comment.ownerId||comment.authorId||null,label}]}]}]};}
async function persistCurrentDraft(){if(restored.value)await saveCommentDraft(draftKey.value,{document:document.value,attachments:attachments.value.map(({previewUrl:_preview,...asset})=>asset),savedAt:Date.now()});}

function openFullscreen(){if(fullscreen.value)return;history.pushState({...history.state,onixCommentEditor:true},"");fullscreen.value=true;}
function closeFullscreen(){if(!fullscreen.value)return;if(history.state?.onixCommentEditor)history.back();else fullscreen.value=false;}
function onPopState(){fullscreen.value=false;}
function onKeydown(event:KeyboardEvent){if(event.key==="Escape"&&fullscreen.value){event.preventDefault();closeFullscreen();}}

function appendAttachments(fileList:FileList|File[]){const accepted=[...fileList].filter((file)=>file.type.startsWith("image/")||file.type.startsWith("video/")).slice(0,4-attachments.value.length);const added=accepted.map((file)=>{const asset=fileToPostAsset(file);attachmentFiles.set(asset.id,file);return{asset,file};});if(!added.length)return;attachments.value=[...attachments.value,...added.map(({asset})=>asset)];added.forEach(({asset,file})=>void uploadAttachment(asset.id,file));}
function updateAttachment(localId:string,remote:PostAsset){attachments.value=attachments.value.map((asset)=>asset.id===localId?{...asset,...remote,id:asset.id,clientId:asset.clientId,assetId:remote.assetId||asset.assetId||remote.id,previewUrl:asset.previewUrl||remote.previewUrl||null}:asset);}
async function uploadAttachment(localId:string,file:File){attachmentControllers.get(localId)?.abort();const controller=new AbortController();attachmentControllers.set(localId,controller);try{const local=attachments.value.find((asset)=>asset.id===localId);if(!local)return;let uploaded=await ContentService.uploadMediaAsset(file,local,{signal:controller.signal,onReserved:(reserved)=>updateAttachment(localId,reserved)});updateAttachment(localId,uploaded);if(uploaded.status==="AVAILABLE"){uploaded=await ContentService.retryMediaAssetProcessing(uploaded.assetId||uploaded.id);updateAttachment(localId,uploaded);}await monitorAttachment(localId,uploaded,controller);}catch(error){markAttachmentFailed(localId,error);}finally{if(attachmentControllers.get(localId)===controller)attachmentControllers.delete(localId);}}
async function monitorAttachment(localId:string,remote:PostAsset,controller:AbortController){const assetId=remote.assetId||remote.id;if(!assetId||isAssetReady(remote)||remote.status==="FAILED")return;let completed=await ContentService.waitForMediaAsset(assetId,{signal:controller.signal,onUpdate:(next)=>updateAttachment(localId,next)});if(completed.status==="AVAILABLE"){completed=await ContentService.retryMediaAssetProcessing(assetId);updateAttachment(localId,completed);completed=await ContentService.waitForMediaAsset(assetId,{signal:controller.signal,onUpdate:(next)=>updateAttachment(localId,next)});}updateAttachment(localId,completed);}
function markAttachmentFailed(localId:string,error:unknown){if(error instanceof DOMException&&error.name==="AbortError")return;attachments.value=attachments.value.map((asset)=>asset.id===localId?{...asset,status:"FAILED"}:asset);showError(error,"Не удалось загрузить вложение");}
async function retryAttachment(asset:PostAsset){const file=attachmentFiles.get(asset.id)||attachmentFiles.get(asset.clientId||"");if(file){await uploadAttachment(asset.id,file);return;}if(!asset.assetId){errorMessage.value="Добавьте исходный файл заново";return;}try{const retried=await ContentService.retryMediaAssetProcessing(asset.assetId);updateAttachment(asset.id,retried);const controller=new AbortController();attachmentControllers.set(asset.id,controller);await monitorAttachment(asset.id,retried,controller);}catch(error){markAttachmentFailed(asset.id,error);}}
function removeAttachment(id:string){const asset=attachments.value.find((item)=>item.id===id);attachmentControllers.get(id)?.abort();attachmentControllers.delete(id);if(asset)revokePreview(asset);attachmentFiles.delete(id);attachments.value=attachments.value.filter((item)=>item.id!==id);document.value={...document.value,blocks:document.value.blocks.filter((block)=>block.assetId!==(asset?.assetId||id))};}
function revokePreview(asset:PostAsset){if(asset.previewUrl?.startsWith("blob:"))URL.revokeObjectURL(asset.previewUrl);}

async function send(){const text=commentDocumentText(document.value).slice(0,4000);if(!allowComments.value||sending.value||(!text&&!attachments.value.length)||visibleLength.value>4000)return;if(!attachmentsReady.value){errorMessage.value="Дождитесь обработки всех вложений или удалите неудачное.";return;}sending.value=true;errorMessage.value="";const key=draftKey.value;try{if(editingComment.value){const updated=await ContentService.updateCommentWithFiles({id:editingComment.value.id,text,document:document.value,attachments:commentMediaAssets(attachments.value)});replaceComment(updated.id,()=>updated);}else{const comment=await ContentService.createComment({postId:postId.value,text,document:document.value,parentId:rootTarget.value,replyToId:replyingTo.value?.id||null,attachments:commentMediaAssets(attachments.value)});if(rootTarget.value){threads.value={...threads.value,[rootTarget.value]:mergeComments(threads.value[rootTarget.value]||[],[comment])};loadedIds.value={...loadedIds.value,[rootTarget.value]:true};roots.value=roots.value.map((root)=>root.id===rootTarget.value?{...root,replyCount:(root.replyCount||0)+1}:root);}else roots.value=mergeComments(roots.value,[comment]);}await deleteCommentDraft(key);attachments.value.forEach(revokePreview);attachments.value=[];attachmentFiles.clear();document.value=emptyCommentDocument();replyingTo.value=null;editingComment.value=null;if(fullscreen.value)closeFullscreen();}catch(error){showError(error,"Не удалось отправить комментарий");}finally{sending.value=false;}}
async function like(comment:CommentItem){try{const reaction=comment.likedByViewer?await ContentService.unlikeComment(comment.id):await ContentService.likeComment(comment.id);replaceComment(comment.id,(item)=>({...item,likedByViewer:reaction.liked,likeCount:reaction.likeCount}));}catch(error){showError(error,"Не удалось обновить реакцию");}}
async function remove(comment:CommentItem){try{await ContentService.deleteComment(comment.id);replaceComment(comment.id,(item)=>({...item,tombstone:true,deletedAt:new Date().toISOString(),text:"",document:emptyCommentDocument()}));}catch(error){showError(error,"Не удалось удалить комментарий");}}
async function pin(comment:CommentItem){try{const pinned=await ContentService.pinComment(comment.id,true);roots.value=[pinned,...roots.value.filter((item)=>item.id!==pinned.id).map((item)=>({...item,pinnedAt:null}))];}catch(error){showError(error,"Не удалось закрепить комментарий");}}
async function hide(comment:CommentItem){try{const hidden=await ContentService.hideComment(comment.id);replaceComment(comment.id,()=>hidden);}catch(error){showError(error,"Не удалось скрыть комментарий");}}
async function report(comment:CommentItem){const reason=window.prompt("Причина жалобы")?.trim();if(!reason)return;try{await ContentService.reportComment(comment.id,reason);}catch(error){showError(error,"Не удалось отправить жалобу");}}
async function copy(comment:CommentItem){await navigator.clipboard?.writeText?.(new URL(`/p/${postId.value}/comments/${comment.id}`,window.location.origin).toString());}
function back(){void router.push(`/p/${encodeURIComponent(postId.value)}`);}
function replaceComment(id:string,transform:(comment:CommentItem)=>CommentItem){roots.value=roots.value.map((item)=>item.id===id?transform(item):item);threads.value=Object.fromEntries(Object.entries(threads.value).map(([key,list])=>[key,list.map((item)=>item.id===id?transform(item):item)]));}
function mergeComments(existing:CommentItem[],incoming:CommentItem[]){const map=new Map(existing.map((comment)=>[comment.id,comment]));incoming.forEach((comment)=>map.set(comment.id,comment));return[...map.values()];}
function showError(error:unknown,fallback:string){errorMessage.value=error instanceof Error?error.message:fallback;}
</script>

<template>
  <section class="threads-page" aria-label="Комментарии">
    <header class="threads-page__header"><button type="button" aria-label="К проекту" @click="back"><ArrowLeft :size="21" /></button><h1>Комментарии</h1><span /></header>
    <nav class="threads-page__sort" aria-label="Сортировка"><button v-for="option in ([['TOP','Лучшие'],['NEWEST','Новые'],['OLDEST','Старые']] as const)" :key="option[0]" type="button" :class="{active:sort===option[0]}" @click="changeSort(option[0])">{{ option[1] }}</button></nav>
    <main class="threads-page__list"><div v-if="loading" class="threads-page__skeleton" aria-label="Загружаем комментарии"><i v-for="n in 3" :key="n" /></div><ThreadComment v-for="comment in roots" v-else :key="comment.id" :comment="comment" :replies="threads[comment.id]||[]" :reply-cursor="replyCursors[comment.id]" :loaded="Boolean(loadedIds[comment.id])" :loading="Boolean(loadingIds[comment.id])" :is-post-owner="isPostOwner" @reply="reply" @load="loadReplies" @load-more="loadReplies($event,true)" @like="like" @edit="edit" @remove="remove" @pin="pin" @hide="hide" @report="report" @copy="copy" /><p v-if="!loading&&!roots.length" class="threads-page__state">Пока нет комментариев</p><button v-if="rootCursor" class="threads-page__more" type="button" @click="loadRoot(true)">Показать ещё</button></main>
    <form v-if="allowComments" class="threads-composer" :class="{'is-fullscreen':fullscreen}" @submit.prevent="send">
      <header v-if="fullscreen" class="threads-composer__full-header"><strong>{{ editingComment?'Редактирование':'Новый комментарий' }}</strong><button type="button" aria-label="Свернуть редактор" @click="closeFullscreen"><Minimize2 :size="19" /></button></header>
      <div v-if="replyingTo" class="threads-composer__reply"><span>Ответ для {{ replyingTo.authorName||replyingTo.author?.username }}</span><button type="button" aria-label="Отменить ответ" @click="switchTarget(null)"><X :size="15" /></button></div>
      <CommentDocumentEditor v-model="document" :attachments="attachments" @add-files="appendAttachments" @remove-attachment="removeAttachment" />
      <div class="threads-composer__bottom"><button type="button" aria-label="Развернуть редактор" @click="openFullscreen"><Maximize2 :size="18" /></button><span>{{ visibleLength }}/4000</span><button type="submit" :disabled="sending||!attachmentsReady||visibleLength>4000||(!visibleLength&&!attachments.length)" aria-label="Отправить"><Send :size="18" /></button></div>
      <div v-if="attachments.some((asset)=>asset.status==='FAILED')" class="threads-composer__failed"><span>Некоторые вложения не обработаны.</span><button v-for="asset in attachments.filter((item)=>item.status==='FAILED')" :key="asset.id" type="button" @click="retryAttachment(asset)"><RotateCcw :size="13" /> Повторить</button></div>
    </form><p v-else class="threads-page__closed">Комментарии отключены автором.</p><p v-if="errorMessage" class="threads-page__error" role="alert">{{ errorMessage }}</p>
  </section>
</template>

<style scoped>
.threads-page{min-height:100dvh;box-sizing:border-box;padding:20px max(18px,calc((100vw - 720px)/2)) 190px;background:#f7f8f9;color:#30343b;font-family:"Nunito","Avenir Next",sans-serif}.threads-page__header{display:grid;grid-template-columns:40px 1fr 40px;align-items:center;margin-bottom:15px}.threads-page__header button{display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:50%;background:#fff;color:#30343b;cursor:pointer}.threads-page h1{margin:0;font-size:18px;text-align:center}.threads-page__sort{display:flex;gap:6px;margin-bottom:18px}.threads-page__sort button{border:0;border-radius:999px;padding:7px 10px;background:transparent;color:#7d8792;font:800 12px/1 inherit;cursor:pointer}.threads-page__sort button.active{background:#e2e6eb;color:#414954}.threads-page__list{display:grid;gap:7px}.threads-page__state,.threads-page__closed,.threads-page__error{margin:28px 0;color:#89919c;font-size:13px;font-weight:800;text-align:center}.threads-page__error{position:fixed;z-index:30;bottom:170px;left:50%;margin:0;max-width:calc(100vw - 32px);padding:9px 12px;border-radius:10px;background:#fff0ee;color:#ae3b32;transform:translateX(-50%)}.threads-page__more{justify-self:center;border:0;border-radius:999px;padding:9px 13px;background:#e3e7eb;color:#596574;font:800 12px/1 inherit;cursor:pointer}.threads-page__skeleton{display:grid;gap:18px}.threads-page__skeleton i{height:82px;border-radius:16px;background:linear-gradient(90deg,#eceff2,#f7f8f9,#eceff2);background-size:200% 100%;animation:pulse 1.2s infinite}.threads-composer{position:fixed;z-index:20;right:0;bottom:0;left:0;display:grid;gap:7px;max-height:54dvh;overflow:auto;padding:10px max(16px,calc((100vw - 720px)/2));border-top:1px solid #e0e3e7;background:#fff}.threads-composer.is-fullscreen{top:0;max-height:none;padding:18px max(20px,calc((100vw - 960px)/2));align-content:start}.threads-composer.is-fullscreen :deep(.comment-document-editor__surface){min-height:calc(100dvh - 180px);max-height:none}.threads-composer__full-header{display:flex;align-items:center;justify-content:space-between}.threads-composer__full-header button,.threads-composer__reply button,.threads-composer__bottom button{display:grid;place-items:center;border:0;background:transparent;color:#5f6b79;cursor:pointer}.threads-composer__reply,.threads-composer__bottom,.threads-composer__failed{display:flex;align-items:center;gap:8px;color:#7c8692;font-size:11px;font-weight:900}.threads-composer__reply button{margin-left:auto}.threads-composer__bottom span{margin-left:auto}.threads-composer__bottom button:last-child{width:35px;height:35px;border-radius:50%;background:#30343b;color:#fff}.threads-composer__bottom button:disabled{opacity:.35;cursor:not-allowed}.threads-composer__failed{color:#ad443d}.threads-composer__failed button{display:flex;align-items:center;gap:4px;border:0;border-radius:999px;padding:5px 8px;background:#fff0ee;color:#ad443d;cursor:pointer}@keyframes pulse{to{background-position:-200% 0}}@media(prefers-reduced-motion:reduce){.threads-page__skeleton i{animation:none}}
</style>
